// Password-gated Channel Performance dashboard. Content is stored as
// base64 here (not a separate static file) so the Node function bundle
// never depends on Vercel including an extra file at build time.
const PASSWORD = "500demos";
const HTML_B64 = "";

function unauthorized(res) {
  res.setHeader("WWW-Authenticate", 'Basic realm="Channel Performance"');
  res.setHeader("X-Robots-Tag", "noindex, nofollow, noarchive");
  res.status(401).send("Authentication required.");
}

export default function handler(req, res) {
  const auth = req.headers.authorization || "";
  const [scheme, encoded] = auth.split(" ");
  if (scheme !== "Basic" || !encoded) return unauthorized(res);

  let decoded;
  try {
    decoded = Buffer.from(encoded, "base64").toString("utf8");
  } catch {
    return unauthorized(res);
  }
  const password = decoded.slice(decoded.indexOf(":") + 1);
  if (password !== PASSWORD) return unauthorized(res);

  const html = Buffer.from(HTML_B64, "base64").toString("utf8");
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("X-Robots-Tag", "noindex, nofollow, noarchive");
  res.setHeader("Cache-Control", "private, no-store");
  res.status(200).send(html);
}
